class Solution {
  public int minOperations(String s) {
    int n = s.length(), best = Integer.MAX_VALUE;
    for (int rot = 0; rot < n; rot++) {
      int cost = rot;
      for (int i = 0; i < n / 2; i++) {
        int a = s.charAt((rot + i) % n) - 'a', b = s.charAt((rot + n - 1 - i) % n) - 'a';
        int d = Math.abs(a - b);
        cost += Math.min(d, 26 - d);
      }
      best = Math.min(best, cost);
    }
    return best;
  }
}
